def _partially_consume_prefix(self, prefix, column):
    lines = []
    current_line = ""
    current_column = 0
    wait_for_nl = False
    for char in prefix:
        if wait_for_nl:
            if char == '\n':
                lines.append(current_line)
                current_line = ""
                current_column = 0
                wait_for_nl = False
            else:
                current_line += char
        else:
            if char == '\t':
                current_column += 4
                current_line += char
            elif char == ' ':
                current_column += 1
                current_line += char
            elif char == '\n':
                lines.append(current_line)
                current_line = ""
                current_column = 0
            else:
                current_line += char
                wait_for_nl = True
    return ''.join(lines), current_line
